:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #142522;
  color: #f4f0df;
  --ink: #142522;
  --paper: #f4f0df;
  --lime: #c7f36b;
  --coral: #ff8068;
  --muted: #8fa39a;
}

* { box-sizing: border-box; }
body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background-color: #142522;
  background-image: radial-gradient(#315047 1px, transparent 1px);
  background-size: 18px 18px;
}
button { font: inherit; }
.board {
  width: min(100%, 760px);
  padding: clamp(24px, 5vw, 44px);
  border: 2px solid #45665a;
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
  box-shadow: 10px 10px 0 #0b1715;
}
.board-header { text-align: center; }
.eyebrow, .team-tag, .period-label, .period-actions span {
  margin: 0;
  font-size: .8rem;
  font-weight: 800;
  letter-spacing: .16em;
}
.eyebrow { color: #547568; }
h1 {
  margin: 8px 0 4px;
  font-size: clamp(1.5rem, 5vw, 2.35rem);
  line-height: 1.15;
  letter-spacing: .04em;
}
.subtitle { margin: 0; color: #52665e; }
.period-panel {
  width: fit-content;
  margin: 26px auto 22px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 17px;
  border-radius: 9px;
  background: var(--ink);
  color: var(--paper);
}
.period-label { color: var(--lime); }
.period-value { min-width: 1ch; font-size: 1.35rem; font-weight: 900; text-align: center; }
.period-total { color: #a9bbb1; }
.teams {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: clamp(8px, 2vw, 18px);
}
.team-card {
  min-width: 0;
  padding: clamp(14px, 3vw, 24px) clamp(10px, 2.5vw, 20px);
  border: 2px solid var(--ink);
  border-radius: 12px;
  text-align: center;
}
.team-home { background: #dff2bc; }
.team-away { background: #ffe0d6; }
.team-tag { color: #52665e; }
.team-card h2 { margin: 5px 0 4px; font-size: clamp(1.15rem, 3vw, 1.55rem); }
.score {
  display: block;
  margin: 0 auto 16px;
  font-variant-numeric: tabular-nums;
  font-size: clamp(3.5rem, 12vw, 6rem);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: .04em;
}
.score-buttons { display: flex; justify-content: center; gap: 7px; }
.score-buttons button, .step-button, .utility-button {
  min-height: 46px;
  border: 2px solid var(--ink);
  border-radius: 8px;
  background: var(--ink);
  color: var(--paper);
  font-weight: 800;
  cursor: pointer;
  transition: transform .12s ease, background-color .12s ease, color .12s ease, box-shadow .12s ease;
}
.score-buttons button { flex: 1; max-width: 72px; padding: 7px 4px; font-size: 1rem; }
.team-home .score-buttons button:hover { background: #537727; }
.team-away .score-buttons button:hover { background: #a94f3c; }
.versus { color: #71857a; font-size: .85rem; font-weight: 900; letter-spacing: .08em; }
button:hover:not(:disabled) { transform: translateY(-2px); box-shadow: 0 3px 0 #8fa39a; }
button:active:not(:disabled) { transform: translateY(1px); box-shadow: none; }
button:focus-visible { outline: 3px solid #568539; outline-offset: 3px; }
button:disabled { opacity: .42; cursor: not-allowed; }
.board-actions {
  margin-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.utility-button { min-height: 44px; padding: 8px 13px; }
.utility-button:hover:not(:disabled) { background: #315047; }
.period-actions { display: flex; align-items: center; gap: 9px; }
.period-actions span { color: #52665e; font-size: .72rem; }
.step-button { width: 42px; min-height: 42px; font-size: 1.3rem; }
.step-button:hover:not(:disabled) { background: #537727; }
.reset-button { border-color: #a94f3c; background: transparent; color: #8c3d2e; }
.reset-button:hover:not(:disabled) { background: #a94f3c; color: white; }
.status { min-height: 1.25em; margin: 12px 0 -12px; color: #52665e; text-align: center; font-size: .9rem; }

@media (max-width: 480px) {
  .board { padding: 22px 16px; }
  .teams { gap: 7px; }
  .team-card { padding: 14px 8px; }
  .score-buttons { gap: 5px; }
  .score-buttons button { min-height: 44px; }
  .board-actions { flex-wrap: wrap; justify-content: center; }
  .period-actions { order: 3; width: 100%; justify-content: center; }
  .utility-button { flex: 1; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; }
}

(() => {
  const scores = { home: 0, away: 0 };
  const history = [];
  let period = 1;

  const homeScore = document.querySelector("#home-score");
  const awayScore = document.querySelector("#away-score");
  const periodDisplay = document.querySelector("#period");
  const undoButton = document.querySelector("#undo");
  const periodDown = document.querySelector("#period-down");
  const periodUp = document.querySelector("#period-up");
  const status = document.querySelector("#status");

  function render() {
    homeScore.textContent = String(scores.home).padStart(2, "0");
    awayScore.textContent = String(scores.away).padStart(2, "0");
    periodDisplay.textContent = String(period);
    undoButton.disabled = history.length === 0;
    periodDown.disabled = period === 1;
    periodUp.disabled = period === 4;
  }

  document.querySelectorAll(".score-buttons button").forEach((button) => {
    button.addEventListener("click", () => {
      const team = button.dataset.team;
      const points = Number(button.dataset.points);
      history.push({ team, previous: scores[team] });
      scores[team] += points;
      status.textContent = `Added ${points} point${points === 1 ? "" : "s"} to ${team === "home" ? "Team A" : "Team B"}.`;
      render();
    });
  });

  undoButton.addEventListener("click", () => {
    const change = history.pop();
    if (!change) return;
    scores[change.team] = change.previous;
    status.textContent = "Last score change undone.";
    render();
  });

  periodDown.addEventListener("click", () => {
    if (period > 1) period -= 1;
    status.textContent = `Period ${period}.`;
    render();
  });

  periodUp.addEventListener("click", () => {
    if (period < 4) period += 1;
    status.textContent = `Period ${period}.`;
    render();
  });

  document.querySelector("#reset").addEventListener("click", () => {
    scores.home = 0;
    scores.away = 0;
    period = 1;
    history.length = 0;
    status.textContent = "Game reset. Scores are zero and period is 1.";
    render();
  });

  render();
})();
